import React, { useState } from 'react'
import { DropdownButton, Dropdown } from 'react-bootstrap'

const SubCategForm = ({
  addSubCateg,
  newSubCateg,
  handleSubCategChange,
  selectedSubCateg,
  handleSelectedSubCategChange,
  subCategories,
  newName,
  handleNameChange,
  newDescription,
  handleDescriptionChange,
  newImage,
  handleImageChange,
  title,
  selectedCateg
}) => {
  return (
    <div>
      <form onSubmit={addSubCateg}>
        <div>
          <h3>{title}</h3>
          <p>Main category:
            <input
              id='mainCateg'
              value={selectedCateg.mainCateg}
              disabled={true}
            />
          </p>
          <div className="webkit-box">Subcategory:
            <input
              id='subCateg'
              value={newSubCateg}
              onChange={handleSubCategChange}
            />
            or
            <DropdownButton class="dropdown-toggle btn btn-secondary" title={selectedSubCateg}
              onSelect={e =>
                handleSelectedSubCategChange(e)
              }
            >
              {subCategories.map(categ => (
                <Dropdown.Item eventKey={categ}>{categ}</Dropdown.Item>
              ))}
            </DropdownButton>
          </div>
          <p>Name:
            <input
              id='name'
              value={newName}
              onChange={handleNameChange}
            />
          </p>
          <p>Description:
            <input
              id='description'
              value={newDescription}
              onChange={handleDescriptionChange}
            />
          </p>
        </div>
        <div className="process">
          <h4 className="process_heading">Image</h4>
          <p className="process_details">Upload image to server</p>

          <input type="file" className="process_upload-btn" onChange={handleImageChange} />
          <img src={newImage !== undefined ? newImage.multerImage : null} alt="upload-image" id="upload-image" className="process_image" />
        </div>
        <br></br>
        <button class="btn btn-success" type="submit" id="save_blog">Create</button>
      </form>
      <br></br>
    </div>
  )}

export default SubCategForm